DEFS = '''<defs>
<linearGradient id="cream" x2="1" y2="1"><stop stop-color="#fcfcf3"/><stop offset="1" stop-color="#dedfd1"/></linearGradient>
<linearGradient id="metal" x2="1" y2="1"><stop stop-color="#c2c8b9"/><stop offset=".5" stop-color="#8d9880"/><stop offset="1" stop-color="#adb79f"/></linearGradient>
<linearGradient id="sage" x2="1" y2=".6"><stop stop-color="#b8c4a2"/><stop offset="1" stop-color="#7a8b64"/></linearGradient>
<linearGradient id="dark" x2="1" y2="1"><stop stop-color="#78846c"/><stop offset="1" stop-color="#3d4b35"/></linearGradient>
<pattern id="mesh" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="#647159"/><circle cx="3" cy="3" r="1.1" fill="#354530"/></pattern>
<filter id="shadow" x="-.5" y="-.5" width="2" height="2"><feDropShadow dx="5" dy="14" stdDeviation="10" flood-color="#394331" flood-opacity=".15"/></filter>
</defs>'''


def main():
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    products = json.loads(PRODUCTS_PATH.read_text(encoding="utf-8"))
    for p in products:
        color = CATEGORY_COLORS.get(p["category"], "#e6e9e2")
        artwork = ART[p.get("illustration", p["id"])]
        if "illustration" in p:
            # Reused shapes keep their product silhouette, without old labels.
            if isinstance(p["illustration"], int):
                artwork = re.sub(r"<text\b[^>]*>.*?</text>", "", artwork)
            angle = (-5, 0, 5)[p["id"] % 3]
            artwork = f'<g transform="rotate({angle} 240 240)">{artwork}</g>'
        svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="480" height="480" viewBox="0 0 480 480" role="img" aria-labelledby="title"><title id="title">{escape(p['name'])} — illustration</title>{DEFS}<rect width="480" height="480" fill="{color}"/><ellipse cx="243" cy="389" rx="121" ry="13" fill="#384930" opacity=".06"/><g filter="url(#shadow)">{artwork}</g></svg>'''
        (OUT_DIR / p["image"]).write_text(svg, encoding="utf-8")
    print(f"Generated {len(products)} product illustrations in {OUT_DIR}")


if __name__ == "__main__":
    main()
